/* ---------- rutas ---------- */
var VISTAS={despacho:vDespacho,agenda:vAgenda,documentos:vDocumentos,telegramas:vTelegramas,campana:vCampana,secretarias:vSecretarias,hacienda:vHacienda,archivo:vArchivo,pendientes:vPendientes,oficina:vOficina};
function ruta(){
 var p=perfilActual(),parts=(location.hash||p.inicio).slice(1).split('/'),v=parts[0];if(!p.rutas.includes(v)||v==='secretarias'&&parts[1]&&!p.areas.includes(parts[1])||v==='hacienda'&&!p.economia&&parts[1]!=='empresas'){location.replace(p.inicio);return}if(v==='oficina'&&!p.direccion&&!YO.roles.gobernacion&&parts[1]!=='peticiones'){location.replace('#oficina/peticiones');return}
 var v=(location.hash||'#despacho').slice(1).split('/')[0];if(!VISTAS[v])v='despacho';
 var menuVista=v==='secretarias'&&location.hash.split('/')[1]==='festejos'?'festejos':v;$$('.menu a').forEach(function(a){a.classList.toggle('on',a.dataset.v===menuVista);if(a.dataset.v){if(a.dataset.v===menuVista)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}});
 document.title=({despacho:'Mesa de trabajo',campana:'Oficina de campaña',agenda:'Agenda y encuentros',telegramas:'Telégrafo',documentos:'Documentos y firmas',secretarias:'Secretarías',hacienda:'Tesorería y cuentas',archivo:'Archivo oficial',pendientes:'Bandeja de asuntos',oficina:'Secretaría personal'}[v])+' · Partido Republicano · Silver Peak';repMenuCerrar();
 vista.innerHTML='<p class="cargando" role="status">Whitmore está abriendo el libro…</p>';VISTAS[v]();try{vista.focus({preventScroll:true})}catch(e){}
}
