function rubricaDocumento(d,fp){return firmaVincent(d)?'<img class="doc-firma-vincent" src="../firma-vincent.webp" alt="Firma de Vincent Harrington" width="320" height="96">':'<div class="rubrica">'+esc(fp.nombre)+'</div>'}
