 h+='<section class="rep-campana-intro"><div><span class="pre">PARTIDO REPUBLICANO · ELECCIONES DE 1880</span><h2>De la postulación a las urnas.</h2><p>El escrito, las ideas y los encuentros de nuestra candidatura, con la correspondencia y las resoluciones que se reciban.</p></div><img class="rep-escudo" src="img/escudo-republicano.webp" alt="Escudo del Partido Republicano" width="100" height="100"></section><ol class="rep-recorrido" aria-label="Etapas de la candidatura">'+['Preparar la postulación','Presentación y respuesta','Campaña y encuentros','Escrutinio y resultado'].map(function(t,i){return '<li'+(i===paso?' class="actual" aria-current="step"':i<paso?' class="anterior"':'')+'><span>0'+(i+1)+'</span>'+t+'</li>'}).join('')+'</ol>';
