 if(ed){h+='<form id="campExp">'+campo('titulo','Encabezamiento',d.titulo||'Postulación a Gobernador de Silver Peak')+campo('texto','Escrito de postulación',d.texto,true)+'<div class="dos"><label class="campo">Tramitación<select name="estado"'+(!res?' disabled':'')+'>'+opciones(estados,exp?exp.estado:'borrador')+'</select></label><label class="campo">Acta del escrutinio<select name="resultado"'+(!res?' disabled':'')+'>'+opciones(resultados,d.resultado||'pendiente')+'</select></label></div>'+'<details class="rep-seguimiento"><summary>Correspondencia, escrutinio y acta oficial</summary>'+campo('resolucion','Correspondencia del staff: respuesta y referencia',d.resolucion,true)+campo('votos','Recuento de votos: candidatos y cifras',d.votos,true)+campo('acta','Acta o confirmación oficial del resultado',d.acta,true)+'</details><button class="btn oro" type="submit">Asentar en el expediente</button></form>';}else h+='<article class="recibido">'+esc(d.texto||'La postulación aún está pendiente de redacción.')+'</article><p>'+esc(d.resolucion||'No se ha recibido resolución.')+'</p><p>'+esc(d.votos||'Sin escrutinio registrado.')+'</p><p>'+esc(d.acta||'')+'</p>';
 h+='</section><div class="fila">';
