/* Secretaría personal del Gobernador. La Presidencia representa la valoración real de administración. */
var OF_EST={recibida:'Petición recibida',en_valoracion:'En valoración por la Presidencia',aclaraciones:'Aclaraciones solicitadas',autorizada:'Autorizada',condicionada:'Autorizada con condiciones',denegada:'No autorizada',en_curso:'En curso',cumplida:'Cumplida'};
