function ofCampo(n,l,v,multi,req){return '<label class="campo">'+l+(multi?'<textarea name="'+n+'" rows="4" maxlength="2500"'+(req?' required':'')+'>'+esc(v||'')+'</textarea>':'<input name="'+n+'" value="'+esc(v||'')+'" maxlength="500"'+(req?' required':'')+'>')+'</label>'}
