function ofEnlace(r){return r.tipo==='peticion'?'#oficina/peticiones/'+r.id:r.tipo==='secretaria'?(r.datos.area?'#secretarias/'+r.datos.area+'/'+r.id:'#secretarias'):r.tipo==='decreto'?'#documentos/'+r.id:r.tipo==='telegrama'?'#telegramas/'+r.id:r.tipo==='acta'?'#archivo':r.tipo==='reunion'?'#oficina/reuniones/'+r.id:r.tipo==='audiencia'||r.tipo==='cita'?'#agenda':'#despacho'}
function ofAsunto(r){return r.datos.titulo||r.datos.texto||r.datos.quien||r.datos.con||'Asunto del Consejo'}
function ofReferencias(rows,id){return rows.filter(function(x){return x.datos.peticion_id===id||(x.datos.asuntos||[]).some(function(a){return a.id===id})}).map(function(x){return '<a class="of-vinculo" href="'+ofEnlace(x)+'"><b>'+esc(cap(x.tipo))+'</b><span>'+esc(ofAsunto(x))+'</span><small>'+esc(x.estado)+'</small></a>'}).join('')}
function ofSeleccion(rows){var pendientes=rows.filter(function(r){return ['peticion','secretaria','decreto','audiencia','telegrama','tarea'].indexOf(r.tipo)>=0&&['firmado','cumplida','denegada','cerrada','hecha','ejecutado','concluido','archivado','descartado'].indexOf(r.estado)<0});return '<fieldset class="of-seleccion"><legend>Asuntos para incluir · máximo 20</legend>'+pendientes.slice(0,60).map(function(r){return '<label><input type="checkbox" name="asuntos" value="'+r.id+'"><span><b>'+esc(cap(r.tipo))+'</b> · '+esc(ofAsunto(r))+(r.tipo==='peticion'&&!ofAutorizada(r)?'<small>Sin autorización de ejecución</small>':'')+'</span></label>'}).join('')+(pendientes.length?'':'<p class="nota">No hay asuntos recientes para seleccionar.</p>')+'</fieldset>'}
function ofAutorizada(r){return ['autorizada','condicionada','en_curso','cumplida'].indexOf(r.estado)>=0}
