  h+='<section class="of-whitmore"><div class="retrato gr"><img class="cara" src="img/whitmore.webp" alt="Sr. Whitmore" width="74" height="104"><img class="marco" src="img/marco-ovalado.webp" alt="" width="112" height="148"></div><div><span class="pre">EL DESPACHO DEL DÍA · 1880</span><h2>'+saludo()+', '+esc(YO.nombre.split(' ')[0])+'.</h2><p>En los libros recientes constan <b>'+esperan.length+' peticiones pendientes de valoración</b>, <b>'+tareas.length+' encargos abiertos</b> y <b>'+proximas.length+' encuentros próximos</b>.</p><p>Los compromisos se limitan a lo autorizado por la Presidencia. La revisión interna de una petición no supone un plazo anunciado al ciudadano.</p><span class="firma-w">Whitmore</span></div></section><div class="of-mesa">'+[['peticiones','Escuchar y tramitar',esperan.length+' peticiones por revisar','i-sobre.webp'],['reuniones','Preparar el Consejo',proximas.length+' encuentros próximos','i-calendario.webp'],['compromisos','Seguir lo autorizado',comp.length+' actuaciones autorizadas','i-pergamino.webp'],['relevo','Dejar el despacho en orden','Lo atendido y la próxima actuación','i-pluma.webp']].map(function(a){return '<a href="#oficina/'+a[0]+'"><img src="img/'+a[3]+'" alt="" width="45" height="45"><h3>'+a[1]+'</h3><p>'+a[2]+'</p><span>Abrir el libro →</span></a>'}).join('')+'</div><section class="tarjeta"><h2>En la carpeta del día</h2>'+esperan.slice(0,6).map(function(r){return '<a class="of-vinculo" href="#oficina/peticiones/'+r.id+'"><b>'+esc(r.datos.ciudadano)+'</b><span>'+esc(r.datos.titulo)+'</span><small>'+esc(OF_EST[r.estado])+'</small></a>'}).join('')+(!esperan.length?'<p class="nota">No hay peticiones pendientes en la selección reciente.</p>':'')+'</section>';
