var secLibro=[],secUltimaArea='',secFiltro='',secBuscar='';
var SEC_EST={en_tramite:'En mesa de Secretaría',pendiente_firma:'En la mesa de Gobernación',autorizado:'Con autorización de Gobernación',devuelto:'Devuelto para enmienda',ejecutado:'Asiento ejecutado',concluido:'Asunto concluido',archivado:'Archivado'};
function secFecha(t){var d=fechaMadrid(t);return d.getDate()+'/'+(d.getMonth()+1)+'/1880'}
function comercioPanel(a,rows){var clases=['licencia','ambulante','explotacion','renovacion'],lic=rows.filter(function(r){return clases.indexOf(r.datos.clase)>=0});return '<section class="tarjeta"><h2>La mesa de Comercio, Minas y Explotaciones</h2><p>Gestione empresas y actividades, tramite sus licencias y eleve las resoluciones a Gobernación. Las tasas o gastos se autorizan en Economía.</p><div class="acciones"><a class="btn oro" href="#hacienda/empresas">Registro de empresas y explotaciones</a>'+ (a.gestiona?[['licencia','Licencia de negocio'],['ambulante','Venta ambulante'],['mina','Ficha de mina'],['explotacion','Permiso de explotación'],['renovacion','Renovar licencia'],['revocacion','Proponer revocación']].map(function(x){return '<button class="btn" data-festejo-nuevo="'+x[0]+'">'+x[1]+'</button>'}).join(''):'')+'</div><h3>Licencias y vigencias</h3>'+(lic.length?lic.map(function(r){var revocada=rows.some(function(x){return x.datos.clase==='revocacion'&&Number(x.datos.relacionado)===r.id&&['autorizado','concluido'].includes(x.estadoActual)}),estado=revocada?'Revocada':!['autorizado','concluido'].includes(r.estadoActual)?'Pendiente de autorización':r.datos.vence&&new Date(r.datos.vence)<new Date()?'Caducada':'Vigente';return '<article class="item"><div><b>'+esc(r.datos.titulo)+'</b><p>'+esc(r.datos.interesado||'Titular pendiente')+' · '+esc(estado)+(r.datos.vence?' · vence '+esc(secFecha(r.datos.vence)):'')+'</p></div><a class="btn" href="#secretarias/comercio/'+r.id+'">Abrir licencia</a></article>'}).join(''):'<p class="nota">Las solicitudes quedarán aquí con su estado, titular y vencimiento.</p>')+'</section>'}
function festejosPanel(a,rows){var agenda=rows.filter(function(r){return r.cuando&&['evento','cultural','concurso','anuncio'].indexOf(r.datos.clase)>=0&&['archivado','concluido','ejecutado'].indexOf(r.estadoActual)<0}).sort(function(x,y){return new Date(x.cuando)-new Date(y.cuando)});return '<section class="tarjeta"><h2>La mesa de Festejos y Cultura</h2><p>Prepare la idea, consulte su viabilidad con la Presidencia y eleve el escrito al Gobernador. Solo el programa autorizado está listo para anunciar; las fechas de planificación son provisionales.</p><div class="acciones">'+(a.gestiona?[['evento','Proponer un festejo'],['cultural','Proyecto cultural'],['concurso','Preparar concurso'],['presupuesto','Preparar presupuesto'],['contacto','Añadir colaborador'],['anuncio','Preparar programa']].map(function(x){return '<button class="btn" data-festejo-nuevo="'+x[0]+'">'+x[1]+'</button>'}).join(''):'')+'</div><h3>Calendario de planificación</h3>'+(agenda.length?agenda.map(function(r){return '<article class="item"><div><b>'+esc(r.datos.titulo)+'</b><p>'+esc(new Date(r.cuando).toLocaleString('es-ES',{timeZone:'Europe/Madrid',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit'}))+' · '+esc(SEC_EST[r.estadoActual]||r.estadoActual)+'</p></div><a class="btn" href="#secretarias/festejos/'+r.id+'">Abrir carpeta</a></article>'}).join(''):'<p class="nota">Las actividades con fecha prevista aparecerán aquí al guardar su expediente.</p>')+'<h3>Libros conectados con Discord</h3><div class="acciones">'+[['festejos_despacho','Despacho'],['area_festejos','Expedientes'],['festejos_calendario','Calendario'],['festejos_presupuestos','Presupuestos'],['festejos_cultura','Cultura y colaboradores'],['festejos_programa','Programa autorizado']].map(function(x){return repCanal(x[0],x[1])}).join('')+'</div></section>'}
function secResponsables(a){var c=a.competencia;return c.modo==='gobernador'?'Gobernador · responsabilidad principal'+(c.delegadaVice?' · delegación vigente en el Vicegobernador':''):c.modo==='direccion_conjunta'?'Gobernador y Vicegobernador · competencia conjunta':c.modo==='secretaria_comercio'?'Secretaría de Comercio, Minas y Explotaciones':c.modo==='secretaria_economia'?'Gobernador':c.modo==='secretaria_festejos'?'Secretaría de Festejos y Cultura':(c.titulares||[]).map(function(t){return t.nombre}).join(' · ')||'Pendiente de designación'}
function secCampo(n,l,v,grande,max){return '<label class="campo">'+l+(grande?'<textarea name="'+n+'" rows="'+(n==='texto'?8:3)+'" maxlength="'+(max||3000)+'">'+esc(v||'')+'</textarea>':'<input name="'+n+'" maxlength="'+(max||200)+'" value="'+esc(v||'')+'">')+'</label>'}
