  if(area.id==='economia'&&perfilActual().puedeDelegarEconomia)h+='<section class="tarjeta"><h2>Responsabilidad y delegación económica</h2><p>La responsabilidad principal corresponde al Gobernador. La delegación permite al Vicegobernador gestionar Economía y firmar asuntos económicos, hasta su retirada.</p><button class="btn oro" id="ecoDelegar" data-delegar="'+(!j.delegacionEconomica)+'">'+(j.delegacionEconomica?'Retirar delegación económica':'Delegar Economía en el Vicegobernador')+'</button></section>';if(area.id==='comercio')h+=comercioPanel(area,secLibro)+'<section class="tarjeta"><h3>Libros de Comercio en Discord</h3><div class="acciones">'+[['comercio_despacho','Despacho'],['area_comercio','Expedientes'],['comercio_licencias','Licencias y venta ambulante'],['comercio_explotaciones','Minas y explotaciones'],['comercio_empresas','Empresas'],['comercio_seguimiento','Inspecciones']].map(function(x){return repCanal(x[0],x[1])}).join('')+'</div></section>';if(area.id==='festejos')h+=festejosPanel(area,secLibro);
